import type { CanonicalRide, Row } from '../harness';

const fix = (elapsedSeconds: number, timestamp: string, active: number, values: Row): Row => ({
  elapsedSeconds,
  timestamp,
  producer: 'phone',
  active,
  ...values,
});

const event = (elapsedSeconds: number, timestamp: string, action: string, interrupted = 0) => ({
  elapsedSeconds,
  timestamp,
  producer: 'phone',
  action,
  interrupted,
});

